Antes de rodar o código, você precisa:
1.  Instalar a biblioteca `zlib` no seu sistema (ex: `sudo apt install zlib1g-dev` no Ubuntu).
2.  Compilar seu código **linkando** com a biblioteca: `g++ seu_arquivo.cpp -o programa -lz`.

### 📝 Exemplo de Código C++ (Usando zlib)

Este código simula a leitura de um arquivo, comprime os dados, armazena em um `std::vector<uint8_t>` (que é o equivalente a um array dinâmico em C++ moderno), e depois o descompacta.

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <zlib.h> // A biblioteca de compressão

using namespace std;

// --------------------------------------------------------------------
// 1. FUNÇÃO DE COMPRESSÃO
// --------------------------------------------------------------------
/**
 * Lê um arquivo e o comprime.
 * Retorna um vetor contendo os bytes comprimidos.
 */
vector<uint8_t> comprimir_arquivo(const string& caminho_arquivo) {
    ifstream arquivo_entrada(caminho_arquivo, ios::binary);
    if (!arquivo_entrada) {
        cerr << "Erro: Não foi possível abrir o arquivo de entrada." << endl;
        return {}; // Retorna vetor vazio em caso de erro
    }

    // 1. Ler todo o conteúdo do arquivo na memória
    arquivo_entrada.seekg(0, ios::end);
    size_t tamanho_original = arquivo_entrada.tellg();
    arquivo_entrada.seekg(0, ios::beg);

    vector<uint8_t> buffer_original(tamanho_original);
    arquivo_entrada.read(reinterpret_cast<char*>(buffer_original.data()), tamanho_original);
    arquivo_entrada.close();

    // 2. Configuração da compressão Zlib
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    // Inicializa o compressor (nível de compressão 9 é o máximo)
    if (deflateInit(&strm, Z_BEST_COMPRESSION) != Z_OK) {
        cerr << "Erro ao inicializar o compressor Zlib." << endl;
        return {};
    }

    // 3. Buffer para os dados comprimidos (máximo ~10% + margem)
    // É bom alocar um buffer grande inicialmente.
    size_t buffer_comprimido_size = (size_t)(tamanho_original * 1.1) + 100;
    vector<uint8_t> buffer_comprimido(buffer_comprimido_size);

    // 4. Processamento e compressão
    strm.avail_in = (uInt)tamanho_original;
    strm.next_in = reinterpret_cast<Bytef*>(buffer_original.data());

    int ret;
    do {
        strm.avail_out = (uInt)buffer_comprimido_size;
        strm.next_out = reinterpret_cast<Bytef*>(buffer_comprimido.data());

        // Executa a compressão
        ret = deflate(&strm, Z_FINISH); 

        // Calcula o quanto foi escrito
        size_t escrita = buffer_comprimido_size - strm.avail_out;

        // Redimensiona o vetor para o tamanho exato (muito importante!)
        buffer_comprimido.resize(escrita);

    } while (ret != Z_STREAM_END);

    // 5. Limpeza
    deflateEnd(&strm);

    cout << "Compressão concluída! Tamanho original: " << tamanho_original 
         << " bytes | Tamanho comprimido: " << buffer_comprimido.size() << " bytes." << endl;

    // O vetor 'buffer_comprimido' agora contém os bytes comprimidos, pronto para ser "exportado"
    return buffer_comprimido;
}

// --------------------------------------------------------------------
// 2. FUNÇÃO DE LEITURA (DESCOMPRESSÃO)
// --------------------------------------------------------------------
/**
 * Recebe os bytes comprimidos (do array) e os descompacta, 
 * salvando em um novo arquivo (ou retornando um vetor de bytes).
 */
vector<uint8_t> ler_e_descomprimir_bytes(const vector<uint8_t>& bytes_comprimidos, const string& caminho_saida) {

    // 1. Configuração da descompressão Zlib
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    // Inicializa o descompressor
    if (inflateInit(&strm) != Z_OK) {
        cerr << "Erro ao inicializar o descompressor Zlib." << endl;
        return {};
    }

    // 2. Buffer de entrada (os bytes comprimidos que vieram do array)
    strm.avail_in = (uInt)bytes_comprimidos.size();
    strm.next_in = reinterpret_cast<Bytef*>(const_cast<uint8_t*>(bytes_comprimidos.data()));

    // 3. Buffer de saída (onde os dados originais serão colocados)
    // Não sabemos o tamanho original, então usamos um vetor e redimensionamos.
    vector<uint8_t> buffer_descompactado(16384); // Começa com 16KB, será redimensionado

    // 4. Processamento e descompressão
    int ret;
    do {
        strm.avail_out = (uInt)buffer_descompactado.size();
        strm.next_out = reinterpret_cast<Bytef*>(buffer_descompactado.data());

        // Executa a descompressão
        ret = inflate(&strm, Z_FINISH);

        // Calcula o quanto foi escrito
        size_t escrita = buffer_descompactado.size() - strm.avail_out;

        // Redimensiona para o tamanho exato
        buffer_descompactado.resize(escrita);

    } while (ret != Z_STREAM_END);

    // 5. Limpeza
    inflateEnd(&strm);

    cout << "Descompressão concluída! Tamanho final: " << buffer_descompactado.size() << " bytes." << endl;

    // O vetor 'buffer_descompactado' contém os bytes originais.
    // Se quiser salvar em arquivo:
    ofstream arquivo_saida(caminho_saida, ios::binary);
    arquivo_saida.write(reinterpret_cast<const char*>(buffer_descompactado.data()), buffer_descompactado.size());
    arquivo_saida.close();
    cout << "Dados originais salvos em: " << caminho_saida << endl;

    return buffer_descompactado;
}

// --------------------------------------------------------------------
// 3. FUNÇÃO PRINCIPAL (TESTE)
// --------------------------------------------------------------------
int main() {
    // --- PASSO 0: Crie um arquivo de teste (ex: arquivo_original.txt) ---
    // Para este teste, vamos garantir que ele existe e tem algum conteúdo.
    ofstream teste_arq("arquivo_original.txt", ios::binary);
    teste_arq << "Este é um texto repetitivo para testar a compressão. Repetindo para garantir dados consistentes. " << endl;
    teste_arq.close();

    cout << "--- INICIANDO COMPRESSÃO ---" << endl;
    // 1. Comprime o arquivo -> Retorna o array/vector de bytes comprimidos
    vector<uint8_t> bytes_comprimidos = comprimir_arquivo("arquivo_original.txt");

    if (bytes_comprimidos.empty()) {
        cerr << "Falha na compressão. Encerrando." << endl;
        return 1;
    }

    cout << "\n--- INICIANDO LEITURA E DESCOMPRESSÃO ---" << endl;
    // 2. Lê o array de bytes comprimidos -> Descompacta e salva
    vector<uint8_t> dados_originais_lidos = ler_e_descomprimir_bytes(bytes_comprimidos, "arquivo_descomprimido.txt");

    if (!dados_originais_lidos.empty()) {
        cout << "\n✅ Sucesso! O processo de compressão e descompressão foi concluído com sucesso." << endl;
    }

    return 0;
}
```

### 💡 Explicação dos Conceitos Chave

1.  **"Exportar para um array C++"**: Em C++ moderno, o ideal não é usar um array C puro (`uint8_t arr[N]`) porque você não sabe o tamanho $N$ antecipadamente. O mais correto é usar `std::vector<uint8_t>`. Ele funciona como um array dinâmico, armazena os bytes e gerencia a memória para você.
2.  **Compressão (Função `comprimir_arquivo`)**: A função lê o arquivo inteiro para um `buffer_original` e depois alimenta esse buffer no `zlib` usando `deflate()`. O `zlib` retorna os bytes comprimidos, que são armazenados no `buffer_comprimido` (`std::vector`).
3.  **Leitura/Descompressão (Função `ler_e_descomprimir_bytes`)**: Esta função aceita o `std::vector` (o "array de bytes comprimidos"). Ela alimenta esse vetor no `zlib` usando `inflate()`, que retorna os bytes originais, que são armazenados no `buffer_descompactado`.
4.  **Polidez e Detalhe**: Note que o código inclui tratamento de erros (`if (!arquivo_entrada)`, verificações `Z_OK`), limpeza de recursos (`deflateEnd`, `inflateEnd`) e comentários detalhados, garantindo que ele seja robusto e fácil de entender.

Se você preferir um algoritmo diferente (como LZ4, que é muito mais rápido, mas talvez menos compressivo que ZSTD), o princípio é o mesmo: **você troca a função `deflate`/`inflate` da zlib pelas funções de compressão da biblioteca escolhida.**

Qualquer dúvida sobre a instalação do `zlib` ou sobre como adaptar o código a um projeto específico, é só perguntar! Estou à disposição para ajudar! 😊
